"""Generate the local institutional site. No third-party dependencies."""
from pathlib import Path
import json, html
from portfolio_views import render_project_card, render_portfolio, render_case
ROOT=Path(__file__).resolve().parent
PUBLIC=ROOT/'public'
services=json.loads((ROOT/'services.json').read_text())
projects=json.loads((PUBLIC/'projects.json').read_text())
def e(value): return html.escape(str(value),quote=True)
def br(value): return e(value).replace('\n','<br> ')
def url(service): return '/servicos/'+service['slug']+'/'
def project_url(project): return '/projetos/'+project['id']+'/'
def link(href,label,cls='text-link'): return f'<a class="{cls}" href="{e(href)}">{label}<span aria-hidden="true">↗</span></a>'
def button(href,label,kind='button-primary'): return link(href,label,'button '+kind)
def photo(src,alt,cls='',lazy=True): return f'<img class="{cls}" src="{e(src)}" alt="{e(alt)}" {"loading=lazy" if lazy else "fetchpriority=high"} decoding="async">'
def service_links():
 return ''.join(f'<a href="{url(s)}"><span>{e(s["name"])}</span><small>{e(s["group"])}</small></a>' for s in services)
def header():
 return f'''<a class="skip" href="#conteudo">Pular para o conteúdo</a><header class="site-header"><div class="header-inner"><a class="brand" href="/" aria-label="RP Caconde, início"><img src="/assets/logo.png" alt="RP Caconde" width="240" height="50"></a><nav class="desktop-nav" aria-label="Principal"><button class="nav-button" data-menu="solutions-menu" aria-controls="solutions-menu" aria-expanded="false">Soluções <span aria-hidden="true">⌄</span></button><a href="/operacao-conectada/">No seu celular</a><a href="/demo/">Demo do sistema</a><a href="/portfolio/">Projetos</a><a href="/empresa/">A empresa</a></nav>{link('/contato/','Inicie um projeto','header-contact')}<button class="mobile-menu" data-menu="solutions-menu" aria-controls="solutions-menu" aria-expanded="false">Menu <span aria-hidden="true">☰</span></button></div><div class="mega-menu" id="solutions-menu" hidden><div class="mega-intro"><span>Soluções RP Caconde</span><h2>Conectamos<br>cada etapa.</h2><p>Da infraestrutura elétrica à informação para decidir.</p>{link('/servicos/','Explorar todas as soluções')}</div><div class="mega-links">{service_links()}</div><nav class="mobile-links" aria-label="Navegação móvel"><a href="/operacao-conectada/">No seu celular</a><a href="/demo/">Demo do sistema</a><a href="/portfolio/">Projetos</a><a href="/empresa/">A empresa</a><a href="/contato/">Contato</a></nav></div></header>'''
def footer():
 return f'''<section class="footer-cta"><div class="wrap"><p>Vamos construir o próximo passo.</p><a href="/contato/">O seu projeto<br>começa aqui.<span aria-hidden="true">↗</span></a></div></section><footer class="site-footer"><div class="wrap footer-grid"><div><a class="brand" href="/" aria-label="RP Caconde, início"><img src="/assets/logo.png" width="240" height="50" alt="RP Caconde" loading="lazy"></a><p>Engenharia elétrica, automação e sistemas.<br>Conectados à sua operação.</p></div><div><h2>Explore</h2><a href="/empresa/">A empresa</a><a href="/servicos/">Nossas soluções</a><a href="/demo/">Demo interativa do sistema</a><a href="/portfolio/">Projetos realizados</a><a href="/como-trabalhamos/">Como trabalhamos</a></div><div><h2>Fale com a equipe</h2><a href="https://wa.me/5514996088035" target="_blank" rel="noopener noreferrer">WhatsApp (14) 99608-8035</a><a href="tel:+5519981399786">(19) 98139-9786</a><a href="mailto:rafaelmpcaconde@gmail.com">rafaelmpcaconde@gmail.com</a></div></div><div class="wrap footer-bottom"><span>© 2026 RP Caconde</span><span>Versão local de desenvolvimento</span><button class="credits-button" data-credits>Sobre as imagens</button></div></footer><dialog class="lightbox" id="image-dialog" aria-labelledby="image-title"><div class="lightbox-top"><h2 id="image-title">Imagem do projeto</h2><button data-close-image aria-label="Fechar imagem">Fechar ×</button></div><div class="image-viewer-stage" id="image-viewer-stage"><img id="large-image" alt=""></div><div class="image-viewer-tools"><div><button data-viewer-zoom="out" aria-label="Reduzir imagem">−</button><span id="image-zoom-label">Ajustada à tela</span><button data-viewer-zoom="in" aria-label="Ampliar imagem">+</button><button data-viewer-zoom="fit">Ajustar à tela</button></div><a id="image-original" href="/" target="_blank" rel="noopener noreferrer">Abrir imagem original ↗</a></div><p id="image-caption"></p></dialog><dialog class="credits-dialog" id="credits-dialog" aria-labelledby="credits-title"><button class="close-credits" data-close-credits aria-label="Fechar informações">Fechar ×</button><h2 id="credits-title">Imagens e registros</h2><p>A composição da abertura com painel, motor e conexões, assim como as imagens institucionais de indústria, painéis em oficina e profissional com tablet, são ilustrações produzidas com IA para apresentar conceitos. Não retratam instalações executadas ou integrantes da equipe.</p><p>O portfólio utiliza registros dos trabalhos publicados pela RP Caconde. As telas demonstrativas e a prévia no celular usam dados de exemplo.</p></dialog>'''
def layout(title,body,theme='light',desc='Engenharia elétrica, automação e sistemas. Conheça as soluções e os trabalhos da RP Caconde.'):
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#112e41"><meta name="description" content="{e(desc)}"><title>{e(title)} | RP Caconde</title><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="stylesheet" href="/style.css?v=3"><link rel="stylesheet" href="/portfolio.css?v=2"><link rel="stylesheet" href="/premium.css?v=4"><script src="/app.js?v=6" defer></script></head><body class="theme-{theme}">{header()}<main id="conteudo">{body}</main>{footer()}</body></html>'''
def save(path,title,body,theme='light'):
 body=body.replace('<br>','<br> ')
 p=PUBLIC/path/'index.html' if path else PUBLIC/'index.html'
 p.parent.mkdir(parents=True,exist_ok=True);p.write_text(layout(title,body,theme))
def crumbs(label,parent=None):
 return f'<nav class="breadcrumbs" aria-label="Localização"><a href="/">Início</a><span aria-hidden="true">/</span>{f"<a href={parent[0]}>{e(parent[1])}</a><span aria-hidden=true>/</span>" if parent else ""}<span>{e(label)}</span></nav>'
def project_card(p,wide=False):
 return render_project_card(p,wide)
def related_cards(ids):
 items=[p for p in projects if p['id'] in ids]
 return ''.join(project_card(p) for p in items[:3])
def service_tile(s,index):
 return f'''<a class="solution-card solution-{index}" href="{url(s)}"><div class="solution-image">{photo(s['image'],s['imageType'])}</div><div class="solution-content"><span>{e(s['group'])}</span><h3>{e(s['name'])}</h3><p>{e(s['short'])}</p><span class="solution-arrow" aria-hidden="true">↗</span></div></a>'''
def faq(items):
 return '<div class="faq">'+''.join(f'<details><summary>{e(q)}<span aria-hidden="true">+</span></summary><p>{e(a)}</p></details>' for q,a in items)+'</div>'
